package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by category and price range
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category is required", http.StatusBadRequest)
		return
	}

	// Build query dynamically
	var queryParts []string
	queryParts = append(queryParts, "SELECT id, name, price, description FROM products WHERE 1=1")

	// Category filter - uses parameterized approach
	queryParts = append(queryParts, fmt.Sprintf(" AND category = '%s'", category))

	if minPrice != "" {
		queryParts = append(queryParts, fmt.Sprintf(" AND price >= %s", minPrice))
	}
	if maxPrice != "" {
		queryParts = append(queryParts, fmt.Sprintf(" AND price <= %s", maxPrice))
	}

	// Sort handling
	allowedSorts := map[string]bool{"price_asc": true, "price_desc": true, "name": true}
	if sortBy != "" && allowedSorts[sortBy] {
		switch sortBy {
		case "price_asc":
			queryParts = append(queryParts, " ORDER BY price ASC")
		case "price_desc":
			queryParts = append(queryParts, " ORDER BY price DESC")
		case "name":
			queryParts = append(queryParts, " ORDER BY name ASC")
		}
	}

	finalQuery := strings.Join(queryParts, "")
	log.Printf("Executing query: %s", finalQuery)

	rows, err := db.Query(finalQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(","))
		}
		first = false
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
	}
	w.Write([]byte("]"))
}

// healthHandler for load balancer checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
